mapper.select:
select id, sku_id, sku_no as skuNo, source_id, source_code, source_type, warehouse_id, qty, status, from_warehouse_area, from_warehouse_location, to_warehouse_area, to_warehouse_location, suggest_qty, create_user_name as createUserName, create_time as createTime, update_user_name, update_time, handle_user_id, handle_user_name, handle_time from warehouse_location_replenish where is_deleted = false
and ${params.sqlMap.default}
ORDER BY
${item.field} ${item.sort}
create_time desc
